          description: "\u0641\u064A \u0627\u0644\u0631\u0648\u0628\u0648\u062A\u0627\u062A \u0627\u0644\u0645\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062A\u060C \u062A\u0634\u062F \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062A \u0632\u0648\u0627\u064A\u0627 \u0645\u062E\u062A\u0644\u0641\u0629 \u0644\u062D\u0645\u0644 \u0645\u0646\u0635\u0629 \u0627\u0644\u062A\u062D\u0643\u0645. \u0628\u062A\u062D\u0644\u064A\u0644 \u0642\u0648\u0649 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062A \u0625\u0644\u0649 \u0645\u0631\u0643\u0628\u0627\u062A X \u0648 Y \u0648 Z\u060C \u064A\u062A\u062D\u0643\u0645 \u0627\u0644\u062D\u0627\u0633\u0648\u0628 \u0628\u0627\u062A\u0632\u0627\u0646 \u0627\u0644\u0645\u0646\u0635\u0629 \u0628\u062F\u0642\u0629 \u0645\u0644\u064A\u0645\u062A\u0631\u064A\u0629.",
          practicalTakeaway: "\u062F\u0627\u0626\u0645\u064B\u0627 \u062A\u0623\u0643\u062F \u0623\u0646 \u0627\u0644\u0632\u0627\u0648\u064A\u0629 \u03B8 \u0645\u0642\u0627\u0633\u0629 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0645\u062D\u0648\u0631 \u0627\u0644\u0623\u0641\u0642\u064A \u0642\u0628\u0644 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 cos \u0644\u0644\u0645\u062D\u0648\u0631 x."
