        engineeringTip: "\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062A\u0633\u0627\u0631\u0639 \u062B\u0627\u0628\u062A\u064B\u0627\u060C \u064A\u0645\u0643\u0646\u0643 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0645\u0639\u0627\u062F\u0644\u0627\u062A \u0627\u0644\u062D\u0631\u0643\u0629 \u0627\u0644\u062E\u0637\u064A\u0629 \u0644\u0646\u064A\u0648\u062A\u0646 \u0644\u0644\u062A\u0623\u0643\u062F \u0645\u0646 \u062D\u0633\u0627\u0628\u0627\u062A\u0643!"
